import {languages,lessons,getLessons,allWords,findLesson,getCatalogInfo} from './data.js';
import {hskCharacters} from './datasets/hsk-characters.js';
import {jlptDataset} from './datasets/jlpt-vocabulary.js';
import {japaneseGrammarFoundations} from './datasets/grammar-foundations.js';
import {chineseGrammarFoundations} from './datasets/chinese-grammar.js';
import {migrateImportedWordIds} from './progress-migration.js';

const KEY = 'yukoto.hybrid.v1';
const requestedLang = new URLSearchParams(location.search).get('lang');
const STEPS = ['listen','speak','read','recall'];
const initial = {version:1,settings:{audio:true,roman:true,language:'ja',conversationUrl:'../#conversation'},progress:{ja:{completed:[],words:{},skills:{},streak:0,lastActive:null},zh:{completed:[],words:{},skills:{},streak:0,lastActive:null}}};
function isObj(v){return v!==null && typeof v==='object' && !Array.isArray(v)}
function safeLoad(){try {const v=JSON.parse(localStorage.getItem(KEY));if(!isObj(v)||v.version!==1||!isObj(v.progress))return structuredClone(initial); for(const code of ['ja','zh'])if(!isObj(v.progress[code])||!Array.isArray(v.progress[code].completed)||!isObj(v.progress[code].words)||!isObj(v.progress[code].skills))return structuredClone(initial);const loaded={...structuredClone(initial),...v,settings:{...initial.settings,...v.settings}};if(migrateImportedWordIds(loaded.progress.ja,jlptDataset.words,allWords('ja'))){try{localStorage.setItem(KEY,JSON.stringify(loaded))}catch{/* preserved in memory until save */}}return loaded}catch{return structuredClone(initial)}}
const data = safeLoad();
const state = {charFilter:'all',charQuery:'',charPage:0,grammarLevel:'all',grammarPage:0,selection:{ja:{track:'foundation',level:'foundation',...(data.settings.pathSelection?.ja||{})},zh:{track:'foundation',level:'foundation',...(data.settings.pathSelection?.zh||{})}},pathPage:0,libraryPage:0,lang:languages[requestedLang]?requestedLang:(languages[data.settings.language]?data.settings.language:'ja'),page:'home',practice:'listening',lesson:null,step:0,word:0,answer:null,typed:'',revealed:false,romanRevealed:false,search:'',unit:'all',dueWord:null,spoken:'',recording:false,feedback:'',lastPage:'path'};
const root = document.getElementById('app');
function syncTheme(){document.body.classList.toggle('theme-ja',state.lang==='ja');document.body.classList.toggle('theme-zh',state.lang==='zh');document.documentElement.lang=state.lang==='ja'?'ja':'zh-CN';}
function returnUrl(){return state.lang==='ja'?'../japanese/index.html':'../index.html';}
const escapeHtml = v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const E=escapeHtml;
const iconPaths={
 home:'<path d="M3 10.5 12 3l9 7.5V21h-6v-7H9v7H3z"/>',route:'<circle cx="6" cy="18" r="2"/><path d="M6 16V7a4 4 0 0 1 8 0v10a4 4 0 0 0 8 0v-3"/><circle cx="22" cy="12" r="2"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5z"/>',headphones:'<path d="M3 14v-3a9 9 0 0 1 18 0v3M3 14h5v7H6a3 3 0 0 1-3-3zm18 0h-5v7h2a3 3 0 0 0 3-3z"/>',mic:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10a7 7 0 0 0 14 0M12 17v5m-4 0h8"/>',book:'<path d="M12 6c-3-2-7-2-10-1v15c4-1 7 0 10 2 3-2 6-3 10-2V5c-3-1-7-1-10 1zm0 0v16"/>',pen:'<path d="m4 20 4.5-1L20 7.5 16.5 4 5 15.5zm12.5-16 3.5 3.5"/>',cards:'<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M8 10h8m-8 4h5"/>',chart:'<path d="M4 20V4m0 16h17M8 16l4-5 4 2 4-7"/>',gear:'<circle cx="12" cy="12" r="3"/><path d="m9 2-1 3-3 1-3-1-1 4 3 2v2l-3 2 1 4 3-1 3 1 1 3h6l1-3 3-1 3 1 1-4-3-2v-2l3-2-1-4-3 1-3-1-1-3z"/>',play:'<path d="m8 5 12 7-12 7z"/>',volume:'<path d="M3 9v6h4l5 4V5L7 9zM16 9a5 5 0 0 1 0 6m2-9a9 9 0 0 1 0 12"/>',back:'<path d="m15 18-6-6 6-6"/>',next:'<path d="m9 18 6-6-6-6"/>',check:'<path d="m5 12 4 4L19 6"/>',sparkles:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',arrow:'<path d="M4 12h16m-7-7 7 7-7 7"/>',rotate:'<path d="M3 11a9 9 0 1 1 2 6m-2 4v-6h6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',upload:'<path d="M12 17V5m-5 5 5-5 5 5M4 17v4h16v-4"/>',flame:'<path d="M12 22c-5 0-8-3.6-8-8 0-3.8 3-6 4-10 .5 4 4 4 4 9 2-2 3-4 3-7 3 3 5 6 5 9 0 4-3 7-8 7z"/>',message:'<path d="M4 4h16v12H8l-4 4z"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7z"/><circle cx="12" cy="12" r="3"/>',leaf:'<path d="M20 4C11 4 4 8 4 16c0 3 3 5 6 5 8 0 11-8 10-17zM4 20c4-5 8-8 13-10"/>',checkcircle:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',alert:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6m0 4v.5"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',bookmark:'<path d="M5 3h14v19l-7-5-7 5z"/>',unlock:'<rect x="5" y="10" width="14" height="12" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0"/>'};
function ico(name,size=19){return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.sparkles}</svg>`}
const pd=()=>data.progress[state.lang];
const getW=id=>pd().words[id]||{seen:0,attempts:0,correct:0,ease:2.5,interval:0,due:null,practice:0,marked:false};
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));return true}catch{toast('Storage unavailable. Progress may not persist.');return false}}
function dayStamp(d=new Date()){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}
function touch(){const p=pd(),now=dayStamp();if(p.lastActive!==now){const prev=new Date();prev.setDate(prev.getDate()-1);p.streak=p.lastActive===dayStamp(prev)?(p.streak||0)+1:1;p.lastActive=now}}
function mutateWord(id,fn){touch();const w={...getW(id)};fn(w);pd().words[id]=w;save()}
function seen(id){mutateWord(id,w=>w.seen=(w.seen||0)+1)}
function skill(key){touch();pd().skills[key]=(pd().skills[key]||0)+1;save()}
function practise(id,kind){mutateWord(id,w=>w.practice=(w.practice||0)+1);skill(kind)}
function recall(id,correct){mutateWord(id,w=>{w.attempts=(w.attempts||0)+1;if(correct){w.correct=(w.correct||0)+1;w.ease=Math.max(1.3,(w.ease||2.5)+.1);w.interval=w.interval===0?1:w.interval===1?3:Math.max(1,Math.round(w.interval*w.ease))}else{w.ease=Math.max(1.3,(w.ease||2.5)-.2);w.interval=1}const date=new Date();date.setDate(date.getDate()+w.interval);w.due=date.toISOString()});skill('recall')}
function tracked(id){return getW(id).seen>0||getW(id).attempts>0||getW(id).practice>0}
function dueWords(){
 const dictionary=allWords(state.lang),known=new Set(dictionary.map(w=>w.id));
 const external=Object.entries(pd().words).filter(([id,w])=>!known.has(id)&&w.native&&w.meaning).map(([id,w])=>({id,native:w.native,meaning:w.meaning,roman:w.roman||'',example:'',lessonId:'external',lessonTitle:'Original Yukoto'}));
 return [...dictionary,...external].filter(w=>{const p=getW(w.id);return p.attempts>0&&p.due&&new Date(p.due)<=new Date()});
}
function selection(){return state.selection[state.lang]}
function currentLessons(){const sel=selection();return getLessons(state.lang).filter(l=>l.track===sel.track && (sel.track!=='jlpt' || l.level===sel.level))}
function completed(){const allowed=new Set(currentLessons().map(l=>l.id));return pd().completed.filter(id=>allowed.has(id))}
function overallCompleted(){return pd().completed.filter(id=>Boolean(findLesson(id)&&findLesson(id).language===state.lang))}

function percentage(){return Math.round(100*completed().length/Math.max(1,currentLessons().length))}

function nextLesson(){const finished=new Set(pd().completed);return currentLessons().find(l=>!finished.has(l.id))||null}

function allStats(){const records=Object.values(pd().words);return {completed:overallCompleted().length,seen:records.filter(w=>w.seen>0).length,practised:records.filter(w=>w.practice>0).length,demonstrated:records.filter(w=>w.correct>0).length,attempts:records.reduce((a,b)=>a+(b.attempts||0),0)}}

function mainNav(){return [{id:'home',icon:'home',title:'Dashboard'},{id:'path',icon:'route',title:'My learning path'},{id:'practice',icon:'compass',title:'Free practice'},{id:'library',icon:'cards',title:'Vocabulary library'},{id:'characters',icon:'book',title:state.lang==='ja'?'Kanji & kana':'Hanzi characters'},{id:'grammar',icon:'cards',title:'Grammar patterns'},...(state.lang==='zh'?[{id:'conversation',icon:'message',title:'AI conversation'}]:[]),{id:'review',icon:'rotate',title:'Review & recall'},{id:'progress',icon:'chart',title:'My progress'},{id:'settings',icon:'gear',title:'Settings'}]}
function title(){return {home:'Dashboard',path:'My learning path',practice:'Free practice',library:'Vocabulary library',characters:'Character study',grammar:'Grammar patterns',review:'Review & recall',conversation:'AI conversation',progress:'My progress',settings:'Settings',lesson:'Guided lesson'}[state.page]}
function shell(content){return `<div class="app"><aside class="sidebar"><div class="side-inner"><div class="brand"><div class="brandmark">言</div><div><div class="brandname">yu<span>ko</span><span>to.</span></div><small>LEARN YOUR WAY</small></div></div></div><div><div class="section-label">YOUR STUDIO</div><a class="origin-link" href="${returnUrl()}">${ico('back',16)} Back to ${state.lang==='ja'?'Japanese':'Chinese'} Yukoto</a><nav class="side-nav" aria-label="Main navigation">${mainNav().map(n=>`<button data-page="${n.id}" class="nav-button ${state.page===n.id?'active':''}">${ico(n.icon)}${n.title}</button>`).join('')}</nav></div><div class="side-card"><strong>あなたのペースで。</strong><p>Your own rhythm. Your own journey. Keep exploring; guidance is always here when you need it.</p></div><div class="side-footer">Yukoto · Japanese + Chinese</div></aside><main class="main"><header class="topbar"><div class="top-left"><a class="mobile-brand" href="${returnUrl()}"><span class="mini-mark">言</span> Yukoto</a><div class="crumb">Your studio / <strong>${E(title())}</strong></div></div><div class="top-actions"><a class="mobile-return" href="${returnUrl()}" title="Return to the main Yukoto site">Back to site</a><div class="language-control" role="group" aria-label="Learning language"><button data-lang="ja" aria-pressed="${state.lang==='ja'}" class="${state.lang==='ja'?'selected':''}">日本語</button><button data-lang="zh" aria-pressed="${state.lang==='zh'}" class="${state.lang==='zh'?'selected':''}">中文</button></div><span class="top-streak">${ico('leaf',14)} Your own pace</span></div></header><div class="container fade" id="content">${content}</div><nav class="mobile-bottom" aria-label="Mobile navigation">${[{id:'home',icon:'home',title:'Home'},{id:'path',icon:'route',title:'Learn'},{id:'practice',icon:'compass',title:'Practice'},{id:'progress',icon:'chart',title:'Progress'}].map(n=>`<button data-page="${n.id}" class="${state.page===n.id?'active':''}">${ico(n.icon)}${n.title}</button>`).join('')}</nav></main></div>`}
function heading(eyebrow,text,desc,meta=''){return `<div class="intro"><div><div class="eyebrow">${E(eyebrow)}</div><h1 class="page-heading">${E(text)}</h1><p class="subheading">${E(desc)}</p></div>${meta}</div>`}
function quote(){return state.lang==='ja'?{text:'継続は力なり。',roman:'Keizoku wa chikara nari.',meaning:'Consistency becomes strength.'}:{text:'熟能生巧。',roman:'Shú néng shēng qiǎo.',meaning:'Practice makes perfect.'}}
function home(){const next=nextLesson(),q=quote(),pct=percentage(),stats=allStats(),lg=languages[state.lang];return `${heading('GOOD TO SEE YOU AGAIN','A little progress, every day.',lg.description,`<div class="stat-pill">${ico('leaf',18)} Your pace, your way</div>`)}<section class="hero ${state.lang==='zh'?'hero-zh':''}"><div class="hero-text"><div class="eyebrow">YOUR LANGUAGE, YOUR STORY</div><h2>${E(lg.hello)}<br>Keep your curiosity alive.</h2><p>Continue your guided path, or explore freely. Both move your learning forward.</p><button class="btn" data-page="${next?'lesson':'path'}" ${next?`data-lesson="${next.id}"`:''}>${next?'Continue your journey':'View completed path'} ${ico('arrow',17)}</button></div><div class="hero-art" aria-hidden="true"><div class="sun"></div><div class="mountain m2"></div><div class="mountain"></div><span class="blossom">✿</span><span class="kanji">${state.lang==='ja'?'学':'语'}</span></div></section><div class="dash-grid"><article class="card path-card"><div class="topline"><div class="eyebrow">YOUR GUIDED PATH</div><span class="soft-tag">OPTIONAL · ${E(lg.level)}</span></div><h3>${next?E(next.title):'This selected path is complete!'}</h3><p>${next?E(next.subtitle):'Choose another level or continue free practice and review.'}</p><div class="progress-line"><div class="progress-fill" style="width:${pct}%"></div></div><div class="path-foot"><span>${stats.completed} of ${getLessons(state.lang).length} lessons completed</span><strong>${pct}%</strong></div><button class="btn" data-page="${next?'lesson':'path'}" ${next?`data-lesson="${next.id}"`:''}>${next?'Continue lesson':'View the full path'} ${ico('next',16)}</button></article><article class="card quote-card"><div class="eyebrow">A WORD TO CARRY WITH YOU</div><div class="big-native">${E(q.text)}</div><p>${E(q.roman)}<br>${E(q.meaning)}</p><p class="subline">Progress is made through returning, not rushing.</p></article></div><div class="section-head"><h3>Explore in your own way</h3><button data-page="practice">All practice ${ico('next',12)}</button></div><div class="practice-grid">${practiceCards()}</div><div class="section-head"><h3>What you've been building</h3><button data-page="progress">Your progress ${ico('next',12)}</button></div><div class="stats-grid">${statTiles(stats)}</div>`}
function practiceCards(){return [{id:'listening',icon:'headphones',title:'Listening',desc:'Hear it before you see it'},{id:'speaking',icon:'mic',title:'Speaking',desc:'Find your natural voice'},{id:'reading',icon:'book',title:'Reading',desc:'Understand words in context'},{id:'writing',icon:'pen',title:'Writing',desc:'Recall words from memory'}].map(x=>`<button class="practice-card" data-skill="${x.id}"><span class="icon-wrap">${ico(x.icon,21)}</span><strong>${x.title}</strong><small>${x.desc}</small><span class="next-chevron">${ico('arrow',15)}</span></button>`).join('')}
function statTiles(s){return [{n:s.completed,t:'Lessons finished'},{n:s.seen,t:'Words encountered'},{n:s.practised,t:'Words practised'},{n:s.demonstrated,t:'Words recalled'}].map(x=>`<div class="stat-card"><strong>${x.n}</strong><small>${x.t}</small></div>`).join('')}
function path(){
 const sel=selection(),list=currentLessons(),pct=percentage(),pages=Math.max(1,Math.ceil(list.length/16)),page=Math.min(state.pathPage,pages-1),start=page*16,subset=list.slice(start,start+16),done=new Set(pd().completed);
 const trackOptions=state.lang==='zh'?[['foundation','Guided foundation'],['new','HSK 3.0 · levels 1–6'],['old','HSK 2.0 · levels 1–6']]:[['foundation','Guided foundation'],['hiragana','Hiragana foundations'],['katakana','Katakana foundations'],['jlpt','Curated JLPT-level study']];
 const levels=sel.track==='jlpt'?['Foundation','N5','N4','N3','N2','N1']:(sel.track==='old'||sel.track==='new')?['1','2','3','4','5','6']:[];
 const levelSelect=levels.length?`<label class="curriculum-field">Level<select id="path-level" class="select">${levels.map(x=>`<option value="${E(x)}" ${sel.level===x?'selected':''}>${E(sel.track==='jlpt'?x:'Level '+x)}</option>`).join('')}</select></label>`:'';
 return `${heading('STRUCTURE WHEN YOU WANT IT','Your learning path','Choose a curriculum and level. No prerequisites are locked; every unit remains optional.')}
 <div class="mode-banner"><div><h3>${E(languages[state.lang].label)} · ${E(trackOptions.find(x=>x[0]===sel.track)?.[1]||'Guided learning')}</h3><p>${completed().length} of ${list.length} lessons completed in this selection. ${getCatalogInfo(state.lang).count.toLocaleString()} words and symbols available for independent practice.</p></div><button class="btn btn-light" data-page="practice">Explore freely ${ico('arrow',16)}</button></div>
 <div class="curriculum-toolbar"><label class="curriculum-field">Study track<select id="path-track" class="select">${trackOptions.map(([value,label])=>`<option value="${E(value)}" ${sel.track===value?'selected':''}>${E(label)}</option>`).join('')}</select></label>${levelSelect}<span class="pill">${list.length} lessons · ${Math.round(pct)}% completed</span></div>
 <div class="progress-line lesson-progress"><div class="progress-fill" style="width:${pct}%"></div></div>
 ${state.lang==='ja'&&sel.track==='jlpt'?`<p class="curriculum-notice">The Japanese level tags are curated/community approximations, not official JLPT requirements. ${E(getCatalogInfo('ja').mode)}. The complete JLPT corpus can be imported using npm run sync:jlpt.</p>`:''}
 ${state.lang==='zh'&&sel.track!=='foundation'?'<p class="curriculum-notice">Vocabulary is drawn from the versioned HSK source index. Study sets are automatically grouped; individual word examples come from the recorded source when available. They are not a complete authored grammar course.</p>':''}
 <div class="unit-list">${subset.map(l=>`<article class="lesson-card"><div class="lesson-icon">${E(l.emoji)}</div><div><h3>${E(l.title)}</h3><p>${E(l.subtitle)}</p><div class="lesson-meta"><span>${ico('clock',12)} ${l.time} min</span><span>${l.words.length} items</span></div></div><div class="lesson-end">${done.has(l.id)?'<span class="lesson-done">✓ Completed</span>':''}<button class="btn btn-small ${done.has(l.id)?'btn-light':''}" data-page="lesson" data-lesson="${E(l.id)}">${done.has(l.id)?'Revisit':'Start'} ${ico('arrow',15)}</button></div></article>`).join('')}</div>
 <nav class="study-pagination" aria-label="Guided lesson pages"><button class="btn btn-light btn-small" data-action="path-previous" ${page===0?'disabled':''}>Previous</button><span>Page ${page+1} / ${pages} · ${list.length} units</span><button class="btn btn-light btn-small" data-action="path-next" ${page>=pages-1?'disabled':''}>Next</button></nav>`;
}

function lessonCurrent(){return findLesson(state.lesson)||nextLesson()||getLessons(state.lang)[0]}
function countQuestion(){return Math.min(state.word+1,lessonCurrent().words.length)}
function quizOptions(word){const pool=allWords(state.lang).filter(w=>w.meaning!==word.meaning);let rand=pool.filter((_,i)=>((i*13+word.id.length)%3===0)).slice(0,3).map(w=>w.meaning);for(const w of pool){if(rand.length>=3)break;if(!rand.includes(w.meaning))rand.push(w.meaning)}const answers=[word.meaning,...rand.slice(0,3)];let seed=word.id.split('').reduce((sum,c)=>sum+c.charCodeAt(0),0);return answers.map((v,i)=>({v,key:(i*7+seed)%13})).sort((a,b)=>a.key-b.key).map(x=>x.v)}
function lesson(){const l=lessonCurrent(),step=STEPS[state.step],w=l.words[Math.min(state.word,l.words.length-1)],stepLabel={listen:'Listen first',speak:'Say it aloud',read:'Read in context',recall:'Recall from memory'};let inner='';if(step==='listen'){inner=`<div class="center"><div class="eyebrow">${countQuestion()} / ${l.words.length} · LISTEN & NOTICE</div><div class="practice-big">${E(w.native)}</div><div class="audio-row"><button class="audio-button" data-action="speak" data-text="${E(w.native)}" aria-label="Play native pronunciation">${ico('volume',22)}</button></div>${data.settings.roman?`<div class="roman">${E(w.roman)}</div>`:''}<button class="btn btn-light btn-small" data-action="reveal" style="margin-top:14px">${state.revealed?'Hide meaning':'Reveal meaning'}</button>${state.revealed?`<div class="meaning">${E(w.meaning)}</div><div class="notebook" style="margin-top:16px;text-align:left">${E(w.example)}<br><span class="muted">${E(w.exampleMeaning)}</span></div>`:''}</div>`}else if(step==='speak'){inner=`<div class="center"><div class="eyebrow">SPEAKING PRACTICE</div><div class="practice-big">${E(w.native)}</div>${data.settings.roman?`<div class="roman">${E(w.roman)}</div>`:''}<p class="meaning">${E(w.meaning)}</p><div class="audio-row"><button class="audio-button" data-action="speak" data-text="${E(w.native)}" aria-label="Hear the phrase">${ico('volume',21)}</button><button class="audio-button ${state.recording?'recording':''}" data-action="record" aria-label="${state.recording?'Stop':'Start'} speech recognition">${ico('mic',22)}</button></div><p class="small-note">Listen, repeat, and optionally use the microphone for a transcription check. Recognition is not a pronunciation score.</p>${state.spoken?`<div class="speak-result">Heard: <strong>${E(state.spoken)}</strong></div>`:''}${state.feedback?`<div class="notice">${E(state.feedback)}</div>`:''}<button class="btn btn-light btn-small" data-action="mark-speak">I practised this phrase ${ico('check',15)}</button></div>`}else if(step==='read'){inner=`<div class="eyebrow center">${l.reading.isSentence===false?'WORD STUDY · SOURCE HAS NO SENTENCE':'READING · SOURCE EXAMPLE'}</div><div class="practice-big" style="font-size:clamp(24px,3vw,35px);margin:25px 0">${E(l.reading.native)}</div><div class="audio-row"><button class="audio-button" data-action="speak" data-text="${E(l.reading.native)}" aria-label="Play reading">${ico('volume',21)}</button><button class="btn btn-light btn-small" data-action="reveal">${state.revealed?'Hide reading help':'Show reading help'}</button></div>${state.revealed?`<div class="muted-panel">${data.settings.roman?`<div>${E(l.reading.roman)}</div><div class="divider"></div>`:''}<strong>${E(l.reading.translation)}</strong></div>`:'<div class="center small-note">Try to understand the passage before revealing the help.</div>'}`;}else{const opts=quizOptions(w);inner=`<div class="eyebrow center">${countQuestion()} / ${l.words.length} · RECALL CHECK</div><div class="practice-big">${E(w.native)}</div>${data.settings.roman?`<div class="roman">${E(w.roman)}</div>`:''}<p class="center muted">Choose the closest English meaning.</p><div class="choices">${opts.map((choice,i)=>`<button class="choice ${state.answer!==null?(choice===w.meaning?'correct':state.answer===i?'wrong':''):''}" data-choice="${i}" ${state.answer!==null?'disabled':''}>${E(choice)}${state.answer!==null&&choice===w.meaning?' ✓':''}</button>`).join('')}</div>${state.answer!==null?`<div class="feedback ${opts[state.answer]===w.meaning?'':'bad'}">${opts[state.answer]===w.meaning?'Correct! This word is now scheduled for review.':`Not quite. The correct meaning is “${E(w.meaning)}”. It has been scheduled for another try.`}</div>`:''}`}
const canNext=step!=='recall'||state.answer!==null;return `${heading('GUIDED LEARNING',l.title,l.subtitle)}<div class="practice-panel"><div class="practice-top"><button class="btn btn-light btn-small" data-page="path">${ico('back',15)} Learning path</button><span class="stage-counter">${state.step+1} of 4 stages</span></div><div class="lesson-steps">${STEPS.map((s,i)=>`<button data-step="${i}" class="step ${i===state.step?'active':i<state.step?'complete':''}">${i<state.step?'✓ ':''}${E(stepLabel[s])}</button>`).join('')}</div><div class="mini-progress"><div style="width:${((state.step+(state.step===0||state.step===1?state.word/l.words.length:state.step===3?state.word/l.words.length:0))/4)*100}%"></div></div><h3 class="center" style="margin:22px 0 16px">${E(stepLabel[step])}</h3>${inner}<div class="lesson-actions"><button class="btn btn-ghost" data-action="prev-step">${ico('back',16)} Back</button><button class="btn" data-action="next-step" ${canNext?'':'disabled'}>${state.step===3&&state.word===l.words.length-1?'Complete lesson':(state.step===0||state.step===1||state.step===3)&&state.word<l.words.length-1?'Next phrase':'Continue'} ${ico('arrow',16)}</button></div></div><p class="small-note" style="max-width:960px">You can explore any lesson without completing previous ones. Completing this guided journey records progress only for exercises you actually attempted.</p>`}
function freePractice(){return `${heading('PRACTISE WITHOUT LIMITS','Your practice studio','No locked lessons. Choose the skill, repeat what matters, and move at your pace.')}<div class="tabs" role="tablist" aria-label="Practice skills">${[{id:'listening',name:'Listening'},{id:'speaking',name:'Speaking'},{id:'reading',name:'Reading'},{id:'writing',name:'Writing'}].map(x=>`<button role="tab" aria-selected="${state.practice===x.id}" data-tab="${x.id}" class="tab ${state.practice===x.id?'active':''}">${x.name}</button>`).join('')}</div>${practiceContent()}`}
function practiceContent(){const skillId=state.practice;const list=getLessons(state.lang);if(skillId==='reading'){const l=list[state.word%list.length];return `<div class="practice-panel"><div class="practice-top"><span class="eyebrow">READING · ${E(l.title)}</span><span class="pill">${state.word%list.length+1} / ${list.length}</span></div><div class="practice-big" style="font-size:clamp(25px,3.3vw,40px);margin:25px 0">${E(l.reading.native)}</div><div class="audio-row"><button class="audio-button" data-action="speak" data-text="${E(l.reading.native)}">${ico('volume',22)}</button><button class="btn btn-light btn-small" data-action="reveal">${state.revealed?'Hide translation':'Show translation'}</button></div>${state.revealed?`<div class="muted-panel">${data.settings.roman?`<p>${E(l.reading.roman)}</p>`:''}<strong>${E(l.reading.translation)}</strong></div>`:'<p class="small-note center">Read first. Reveal help when needed.</p>'}<div class="lesson-actions"><button class="btn btn-light" data-action="mark-reading">${ico('check',16)} Mark reading practised</button><button class="btn" data-action="next-free">Next passage ${ico('arrow',16)}</button></div></div>`}
const words=allWords(state.lang);const w=words[state.word%words.length];let center='';if(skillId==='listening'){center=`<div class="eyebrow center">LISTEN FIRST · ${state.word%words.length+1} / ${words.length}</div><div class="audio-row" style="margin:38px 0"><button class="audio-button" style="width:78px;height:78px" data-action="speak" data-text="${E(w.native)}" aria-label="Play phrase">${ico('volume',32)}</button></div><p class="center muted">Listen to the phrase, then reveal the text and meaning.</p><div class="center"><button class="btn btn-light" data-action="reveal">${state.revealed?'Hide phrase':'Reveal phrase'}</button></div>${state.revealed?`<div class="practice-big">${E(w.native)}</div>${data.settings.roman?`<div class="roman">${E(w.roman)}</div>`:''}<p class="meaning">${E(w.meaning)}</p>`:''}`}
if(skillId==='speaking'){center=`<div class="eyebrow center">SPEAKING PRACTICE</div><div class="practice-big">${E(w.native)}</div>${data.settings.roman?`<div class="roman">${E(w.roman)}</div>`:''}<p class="meaning">${E(w.meaning)}</p><div class="audio-row"><button class="audio-button" data-action="speak" data-text="${E(w.native)}" aria-label="Hear phrase">${ico('volume',21)}</button><button class="audio-button ${state.recording?'recording':''}" data-action="record" aria-label="Try voice input">${ico('mic',22)}</button></div>${state.spoken?`<div class="speak-result">Speech recognised: ${E(state.spoken)}</div>`:''}${state.feedback?`<div class="notice">${E(state.feedback)}</div>`:''}<div class="center"><button class="btn btn-light btn-small" data-action="mark-speak">I practised this phrase ${ico('check',15)}</button></div><p class="small-note center">Microphone transcription is optional; it is not an accuracy rating.</p>`}
if(skillId==='writing'){center=`<div class="eyebrow center">RECALL THROUGH WRITING</div><h2 class="center" style="font-size:23px;margin:23px 0">${E(w.meaning)}</h2>${data.settings.roman?`<p class="roman">Hint: ${E(w.roman)}</p>`:''}<label for="write-answer" class="small-note">Write the Japanese/Chinese phrase:</label><textarea class="field" id="write-answer" placeholder="Type in the target language…">${E(state.typed)}</textarea><div class="audio-row"><button class="btn" data-action="check-writing">Check answer ${ico('check',15)}</button><button class="btn btn-light" data-action="reveal">${state.revealed?'Hide answer':'Reveal answer'}</button></div>${state.feedback?`<div class="feedback ${state.feedback.startsWith('Correct')?'':'bad'}">${E(state.feedback)}</div>`:''}${state.revealed?`<div class="center"><div class="practice-big">${E(w.native)}</div></div>`:''}<p class="small-note">Exact-script comparison is used here. Alternative valid expressions and minor typographical differences need human review.</p>`}
return `<div class="practice-panel"><div class="practice-top"><span class="pill">${E(w.lessonTitle)}</span><span class="stage-counter">${state.word%words.length+1} / ${words.length}</span></div>${center}<div class="lesson-actions"><button class="btn btn-light" data-action="prev-free">${ico('back',16)} Previous</button><button class="btn" data-action="next-free">Next phrase ${ico('arrow',16)}</button></div></div>`}
function library(){const words=allWords(state.lang),term=state.search.trim().toLocaleLowerCase(),filter=state.unit;
 const opts=state.lang==='zh'?[['all','All HSK levels'],...['new','old'].flatMap(t=>Array.from({length:6},(_,i)=>[`${t}-${i+1}`,`${t==='new'?'HSK 3.0':'HSK 2.0'} · Level ${i+1}`]))]:[['all','All vocabulary'],['Foundation','Starter words'],...['N5','N4','N3','N2','N1'].map(x=>[x,`${x} · curated`])];
 const filtered=words.filter(w=>(filter==='all'||(state.lang==='zh'?w.levels?.includes(filter):w.level===filter||filter==='Foundation'&&w.lessonTitle?.includes('First connections')))&&(!term||[w.native,w.roman,w.meaning,w.lessonTitle].join(' ').toLocaleLowerCase().includes(term)));
 const shown=filtered.slice(0,(state.libraryPage+1)*48);
 return `${heading('THE WORDS BEHIND YOUR JOURNEY','Vocabulary library','Search, listen, revisit and save tricky words. Encountering a word is not the same as mastering it.')}
 <input class="searchbar" id="vocab-search" aria-label="Search vocabulary" placeholder="Search characters, pronunciation or meaning…" value="${E(state.search)}">
 <div class="filters"><select class="select" id="unit-filter" aria-label="Filter vocabulary level">${opts.map(([id,title])=>`<option value="${E(id)}" ${filter===id?'selected':''}>${E(title)}</option>`).join('')}</select><span class="small-note">Showing ${shown.length} of ${filtered.length} matching entries · ${words.length} unique entries in library</span></div>
 <div class="word-grid">${shown.map(w=>`<article class="vocab-card"><div class="flex between"><span class="pill">${E(w.lessonTitle)}</span>${getW(w.id).correct>0?'<span class="lesson-done">✓ Recalled</span>':''}</div><div class="word-native" style="margin-top:14px">${E(w.native)}</div>${data.settings.roman?`<div class="word-info">${E(w.roman||'')}</div>`:''}<p>${E(w.meaning)}</p><div class="word-controls"><button class="btn btn-light btn-small" data-action="speak" data-text="${E(w.native)}">${ico('volume',14)} Listen</button><button class="btn btn-light btn-small" data-action="encounter" data-word="${E(w.id)}">Mark seen</button><button class="btn btn-light btn-small" data-action="bookmark" data-word="${E(w.id)}">${getW(w.id).marked?'★ Saved':'☆ Save'}</button></div></article>`).join('')}</div>
 ${shown.length<filtered.length?`<div class="study-pagination"><button class="btn" data-action="library-more">Load ${Math.min(48,filtered.length-shown.length)} more · ${filtered.length-shown.length} remaining ${ico('arrow',15)}</button></div>`:''}`;
}

function characters(){
 const isJa=state.lang==='ja';const entries=isJa?jlptDataset.kanji.map(c=>({char:c.char,levels:[c.level],roman:`${Array.isArray(c.on)?c.on.join(' · '):c.on||''} ${Array.isArray(c.kun)?c.kun.join(' · '):c.kun||''}`,meaning:Array.isArray(c.meanings)?c.meanings.join('; '):c.meaning||'',example:c.words?.[0]?.word||'',exampleMeaning:c.words?.[0]?.meaning||'',radical:c.radical||'',components:[]})):hskCharacters.map(c=>({char:c.hanzi,levels:c.levels,roman:c.pinyin,meaning:c.meaning,example:c.exampleChinese,exampleMeaning:c.exampleEnglish,radical:c.radical||'',components:c.components||[]}));
 const levels=isJa?['N5','N4','N3','N2','N1']:['new-1','new-2','new-3','new-4','new-5','new-6'];
 const term=state.charQuery.toLocaleLowerCase();const filtered=entries.filter(c=>(state.charFilter==='all'||c.levels?.includes(state.charFilter))&&(!term||[c.char,c.roman,c.meaning,c.example].join(' ').toLocaleLowerCase().includes(term)));
 const shown=filtered.slice(0,(state.charPage+1)*36);
 return `${heading(isJa?'日本語 · 漢字':'中文 · 汉字',isJa?'Kanji reading studio':'Hanzi reading studio',isJa?'Read the character, study its meanings and listen to its pronunciation. The bundled Japanese list is currently curated; import OpenJLPT for broader community-level coverage.':'Explore the 1,940 HSK 3.0 reading-character assignments at levels 1–6. Character recognition is distinct from word mastery.')}
 <input id="character-search" class="searchbar" placeholder="Search character, reading or meaning…" value="${E(state.charQuery)}" aria-label="Search characters"><div class="filters"><select class="select" id="character-filter"><option value="all">All levels</option>${levels.map(l=>`<option value="${E(l)}" ${state.charFilter===l?'selected':''}>${E(l.toUpperCase())}</option>`).join('')}</select><span class="small-note">${shown.length} of ${filtered.length} character assignments · ${entries.length} total</span></div>
 <div class="character-grid">${shown.map(c=>`<article class="vocab-card character-card"><div class="word-native">${E(c.char)}</div><div class="roman">${E(c.roman||'Reading not supplied')}</div><p>${E(c.meaning||'Meaning not supplied')}</p>${c.radical?`<p class="small-note">Radical: ${E(c.radical)}</p>`:''}${c.example?`<p class="small-note">Example: ${E(c.example)} · ${E(c.exampleMeaning||'')}</p>`:''}<div class="word-controls"><button class="btn btn-light btn-small" data-action="speak" data-text="${E(c.char)}">${ico('volume',14)} Listen</button><button class="btn btn-light btn-small" data-action="encounter" data-word="${E(state.lang)}-character:${E(c.char)}">Mark encountered</button></div></article>`).join('')}</div>
 ${shown.length<filtered.length?`<div class="study-pagination"><button class="btn" data-action="character-more">Load more characters ${ico('arrow',15)}</button></div>`:''}`;
}
function grammar(){
 const isJa=state.lang==='ja';const original=isJa?japaneseGrammarFoundations:chineseGrammarFoundations;
 const extra=isJa?(jlptDataset.grammar||[]).map((item,i)=>({id:item.id||`ja-open-grammar-${i}`,level:item.level,title:item.pattern||item.title||item.grammar||'Pattern',formation:item.formation||'',description:item.meaning||item.description||item.notes||'',examples:(item.examples||[]).map(e=>({native:e.ja||e.native||'',meaning:e.en||e.meaning||''})),source:'OpenJLPT'})):[];
 const entries=[...original,...extra],levels=['all','Foundation',...(isJa?['N5','N4','N3','N2','N1']:[])];const filtered=entries.filter(g=>state.grammarLevel==='all'||g.level===state.grammarLevel);const shown=filtered.slice(0,(state.grammarPage+1)*15);
 return `${heading('UNDERSTAND HOW LANGUAGE WORKS','Grammar patterns',isJa?'Japanese patterns from the original Yukoto guide, plus OpenJLPT grammar when imported.':'A carefully authored Mandarin foundation grammar guide. This is not a complete HSK grammar syllabus.')}
 <div class="filters"><select class="select" id="grammar-filter" aria-label="Filter grammar level">${levels.map(l=>`<option value="${E(l)}" ${state.grammarLevel===l?'selected':''}>${E(l==='all'?'All levels':l)}</option>`).join('')}</select><span class="small-note">${shown.length} / ${filtered.length} patterns available</span></div>
 <div class="grammar-grid">${shown.map(g=>`<article class="card grammar-entry"><span class="pill">${E(g.level)} · ${E(g.source)}</span><h3>${E(g.title)}</h3>${g.formation?`<p class="grammar-formula">${E(g.formation)}</p>`:''}<p>${E(g.description)}</p>${g.examples?.slice(0,2).map(ex=>`<div class="muted-panel"><div class="native-example">${E(ex.native)}</div><div class="small-note">${E(ex.meaning)}</div><button class="btn btn-light btn-small" data-action="speak" data-text="${E(ex.native)}">${ico('volume',14)} Listen</button></div>`).join('')||''}</article>`).join('')}</div>
 ${shown.length<filtered.length?`<div class="study-pagination"><button class="btn" data-action="grammar-more">Load more patterns ${ico('arrow',15)}</button></div>`:''}`;
}
function review(){const due=dueWords(),marked=allWords(state.lang).filter(w=>getW(w.id).marked),work=due.length?due:marked;let w=work.find(x=>x.id===state.dueWord)||work[0];return `${heading('MAKE IT STICK','Review & recall','Spaced review based on real recall attempts. Saved cards can be practised immediately.')}<div class="stats-grid">${statTiles(allStats())}</div><div class="section-head"><h3>Review queue</h3><span class="pill">${due.length} scheduled due · ${marked.length} saved</span></div>${w?`<div class="review-card"><div class="eyebrow">${due.length?'DUE FOR RECALL':'SAVED PRACTICE'}</div><div class="practice-big">${E(w.native)}</div>${data.settings.roman?`<div class="roman">${E(w.roman)}</div>`:''}<div class="audio-row"><button class="audio-button" data-action="speak" data-text="${E(w.native)}">${ico('volume',20)}</button><button class="btn btn-light btn-small" data-action="reveal">${state.revealed?'Hide answer':'Reveal meaning'}</button></div>${state.revealed?`<div class="muted-panel center">${E(w.meaning)}<br><span class="muted">${E(w.example)}</span></div><div class="audio-row"><button class="btn btn-light" data-action="review-answer" data-word="${E(w.id)}" data-correct="false">Again</button><button class="btn" data-action="review-answer" data-word="${E(w.id)}" data-correct="true">I remembered it ${ico('check',15)}</button></div>`:'<div class="center small-note">Try to recall the meaning before revealing the answer.</div>'}</div>`:`<div class="card empty"><div style="font-size:35px">✦</div><strong>Nothing due right now</strong><p>Complete a lesson or save a word in the library to build your review queue.</p><button class="btn" data-page="path">Go to learning path ${ico('arrow',16)}</button></div>`}<p class="small-note">Intervals start at one day, then grow with successful recall. This is a simplified scheduling model, not an independently validated measure of long-term mastery.</p>`}
function progress(){const stats=allStats(),max=allWords(state.lang).length,pct=percentage(),skills=pd().skills;const bars=[['Listening',skills.listening||0],['Speaking',skills.speaking||0],['Reading',skills.reading||0],['Writing',skills.writing||0],['Recall',skills.recall||0]],most=Math.max(...bars.map(x=>x[1]),1);return `${heading('SMALL EFFORTS ADD UP','Your progress','Track Japanese and Chinese separately, with meaningful evidence instead of artificial scores.')}<div class="stats-grid">${statTiles(stats)}</div><div class="section-head"><h3>Guided learning journey</h3></div><div class="card"><div class="flex between"><div><h3>${E(languages[state.lang].label)} guided lessons</h3><p class="small-note">${stats.completed} completed of ${getLessons(state.lang).length} available lessons</p></div><strong style="font-size:28px;color:#5d8269">${pct}%</strong></div><div class="progress-line" style="margin-top:15px"><div class="progress-fill" style="width:${pct}%"></div></div></div><div class="section-head"><h3>Practice activity</h3></div><div class="card"><p class="small-note">Counts represent completed practice actions, not proficiency ratings.</p><div class="skill-list">${bars.map(([name,value])=>`<div class="skill-item"><strong>${name}</strong><div class="progress-line"><div class="progress-fill" style="width:${value/most*100}%"></div></div><span class="right">${value}</span></div>`).join('')}</div></div><div class="section-head"><h3>Evidence of learning</h3></div><div class="card"><p class="small-note">You have encountered <strong>${stats.seen}/${max}</strong> curated words, attempted <strong>${stats.attempts}</strong> recall questions, and correctly recalled <strong>${stats.demonstrated}</strong> distinct words at least once. Words remain subject to review even after successful recall.</p><button class="btn btn-light" data-page="review">Go to review queue ${ico('arrow',15)}</button></div>`}
function conversation(){const configured=Boolean(data.settings.conversationUrl);return `${heading('REAL CONVERSATIONS','Chinese AI conversation','Continue to the existing Yukoto Mandarin conversation experience when its original route is connected.')}<div class="card" style="max-width:820px"><span class="pill">${configured?'Route configured':'Linked to existing page'}</span><h3 style="margin-top:20px">Speak more. Translate less.</h3><p class="subheading">The guided studio links to the original Yukoto Mandarin AI conversation page. Your existing Cloudflare Worker, microphone settings, and instruction policy remain in that application.</p>${configured?`<button class="btn" data-action="open-conversation">Open existing conversation ${ico('arrow',16)}</button>`:`<button class="btn btn-light" data-page="settings">Configure conversation route ${ico('gear',16)}</button>`}<p class="small-note" style="margin-top:20px">The original assistant's Chinese-only response policy, microphone permissions, safety controls and Cloudflare Worker must be maintained in your existing app. The guided studio itself does not send AI requests; the original conversation page manages them.</p></div>`}
function settings(){return `${heading('YOUR SPACE, YOUR RULES','Settings','Configure learning assistance and keep a copy of your progress.')}<div class="card" style="max-width:820px"><div class="setting-row"><div><h3>Show romanisation</h3><p>Display Romaji or Pinyin during lessons. Turn off to strengthen script recognition.</p></div><input class="toggle" type="checkbox" id="setting-roman" ${data.settings.roman?'checked':''} aria-label="Show romanisation"></div><div class="setting-row"><div><h3>Play audio with browser voice</h3><p>Uses your browser's speech synthesis voices. Quality varies by device; no external audio files are required.</p></div><input class="toggle" type="checkbox" id="setting-audio" ${data.settings.audio?'checked':''} aria-label="Enable text to speech"></div><div class="setting-row"><div><h3>Existing Chinese conversation route</h3><p>Set the relative URL or hash of your existing AI page after combining this UI with Yukoto. Example: #/conversation or /conversation.</p></div><input class="select" style="width:190px" id="conversation-url" placeholder="#/conversation" value="${E(data.settings.conversationUrl)}" aria-label="Existing Chinese conversation route"></div><div class="setting-row"><div><h3>Export your learning data</h3><p>Save Japanese and Chinese progress, including recall schedules, as JSON.</p></div><button class="btn btn-light btn-small" data-action="export">${ico('download',15)} Export</button></div><div class="setting-row"><div><h3>Import learning data</h3><p>Restore a Yukoto Hybrid v1 JSON export. Existing progress will be replaced.</p></div><label class="btn btn-light btn-small" for="import-file">${ico('upload',15)} Import</label><input id="import-file" type="file" accept="application/json,.json" class="hidden"></div><div class="setting-row" style="border:0"><div><h3>Reset local progress</h3><p>Erase this browser's learning records for both languages. Cannot be undone without an exported backup.</p></div><button class="btn btn-small" data-action="reset" style="background:#a76362">Reset</button></div></div><div class="section-head"><h3>Integrations and privacy</h3></div><div class="card" style="max-width:820px"><p class="small-note">This standalone integration does not include a connected AI backend or user accounts. Your previous Cloudflare Worker / Gemini Live conversation feature should remain in your existing Yukoto project and be linked during the codebase merge. This prototype does not upload learning progress to a server. Microphone recognition, if enabled, may be processed by your browser's speech service; availability and privacy depend on the browser.</p><p class="notice">Hosted locally or on static hosting: progress is stored only in this browser. Clearing browser data or switching devices may remove it.</p></div>`}
function render(){syncTheme();if(state.page==='lesson'&&(!state.lesson||findLesson(state.lesson)?.language!==state.lang)){state.lesson=nextLesson()?.id||getLessons(state.lang)[0].id}let content={home,path,practice:freePractice,library,characters,grammar,review,conversation,progress,settings,lesson}[state.page]();root.innerHTML=shell(content);}
function toast(message){document.querySelector('.toast')?.remove();const node=document.createElement('div');node.className='toast';node.role='status';node.textContent=message;document.body.appendChild(node);setTimeout(()=>node.remove(),3200)}
function navigate(page,lessonId){const valid=['home','path','practice','library','characters','grammar','review','conversation','progress','settings','lesson'];state.page=valid.includes(page)?page:'home';if(state.page==='lesson'){state.lesson=lessonId||state.lesson||nextLesson()?.id||getLessons(state.lang)[0].id;state.step=0;state.word=0;state.lastPage='path'}state.answer=null;state.revealed=false;state.romanRevealed=false;state.spoken='';state.feedback='';state.recording=false;render();window.scrollTo({top:0,behavior:'instant'})}
function chooseLanguage(lang){if(!languages[lang])return;state.lang=lang;try{history.replaceState(null,'',`?lang=${lang}`)}catch{/* Embedded/offline preview. */}data.settings.language=lang;save();state.word=0;state.unit='all';state.search='';state.pathPage=0;state.libraryPage=0;state.charPage=0;state.grammarPage=0;state.charQuery='';state.charFilter='all';state.grammarLevel='all';state.answer=null;state.revealed=false;state.feedback='';if(state.page==='lesson')state.page='path';render()}
function doSpeak(text){if(!data.settings.audio){toast('Enable audio in Settings first.');return}if(!('speechSynthesis' in window)){toast('Speech synthesis is not supported in this browser.');return}window.speechSynthesis.cancel();const utt=new SpeechSynthesisUtterance(text);utt.lang=languages[state.lang].locale;utt.rate=.85;const voices=window.speechSynthesis.getVoices();const found=voices.find(v=>v.lang.toLowerCase()===utt.lang.toLowerCase())||voices.find(v=>v.lang.startsWith(state.lang));if(found)utt.voice=found;window.speechSynthesis.speak(utt)}
let recognizer=null;
function doRecord(){const Rec=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Rec){toast('Speech recognition is unavailable in this browser. You can still practise aloud.');return}if(state.recording&&recognizer){recognizer.stop();state.recording=false;render();return}try{recognizer=new Rec();recognizer.lang=languages[state.lang].locale;recognizer.maxAlternatives=1;recognizer.interimResults=false;recognizer.onresult=ev=>{state.spoken=ev.results[0][0].transcript;state.feedback='Transcription received. Compare it with the reference and listen again. Recognition alone cannot verify pronunciation.';state.recording=false;render()};recognizer.onerror=ev=>{state.feedback=`Microphone recognition: ${ev.error}. You can still practise aloud and mark your attempt.`;state.recording=false;render()};recognizer.onend=()=>{if(state.recording){state.recording=false;render()}};recognizer.start();state.recording=true;render()}catch{toast('Microphone could not be started. Check permissions.')}}
function finishLesson(){const l=lessonCurrent();touch();if(!pd().completed.includes(l.id))pd().completed.push(l.id);save();navigate('path');toast(`Lesson completed: ${l.title}`)}
function nextStep(){const l=lessonCurrent(),step=STEPS[state.step];if(step==='recall'&&state.answer===null)return;if((step==='listen'||step==='speak'||step==='recall')&&state.word<l.words.length-1){state.word++;if(step==='listen')seen(l.words[state.word].id);if(step==='recall')state.answer=null}else if(state.step===STEPS.length-1){finishLesson();return}else{if(step==='read')skill('reading');state.step++;state.word=0;state.answer=null;state.feedback='';state.spoken='';if(state.step===0)seen(l.words[0].id)}state.revealed=false;render()}
function previousStep(){if(state.word>0&&(state.step===0||state.step===1||state.step===3)){state.word--}else if(state.step>0){state.step--;state.word=0}else{navigate('path');return}state.answer=null;state.revealed=false;state.feedback='';render()}
function markReading(){skill('reading');toast('Reading practice recorded.')}
function markSpeak(){const w=state.page==='lesson'?lessonCurrent().words[state.word]:allWords(state.lang)[state.word%allWords(state.lang).length];practise(w.id,'speaking');toast('Speaking practice recorded.');}
function nextFree(dir){const count=state.practice==='reading'?getLessons(state.lang).length:allWords(state.lang).length;state.word=(state.word+dir+count)%count;state.revealed=false;state.answer=null;state.typed='';state.spoken='';state.feedback='';if(state.practice==='listening')seen(allWords(state.lang)[state.word].id);render()}
function writingCheck(){const w=allWords(state.lang)[state.word%allWords(state.lang).length];const norm=s=>s.normalize('NFKC').replace(/[\s。！!？?、，,.]/g,'').trim();const correct=norm(state.typed)===norm(w.native);if(!state.typed.trim()){state.feedback='Type an answer before checking.';render();return}recall(w.id,correct);skill('writing');state.feedback=correct?'Correct! Your recall attempt has been recorded.':`Not quite. Expected: ${w.native} — ${w.meaning}. Try again after reviewing.`;render()}
function doReview(id,correct){recall(id,correct);state.dueWord=null;state.revealed=false;render();toast(correct?'Scheduled for a later review.':'Scheduled for another review tomorrow.')}
function exportData(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`yukoto-progress-${dayStamp()}.json`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),500)}
function validateImport(obj){if(!isObj(obj)||obj.version!==1||!isObj(obj.settings)||!isObj(obj.progress))return false;for(const lang of ['ja','zh']){const p=obj.progress[lang];if(!isObj(p)||!Array.isArray(p.completed)||!p.completed.every(x=>typeof x==='string')||!isObj(p.words)||!isObj(p.skills))return false;for(const value of Object.values(p.words)){if(!isObj(value)||(!Number.isFinite(value.attempts)&&value.attempts!==undefined))return false}}return true}
root.addEventListener('click',e=>{const el=e.target.closest('button,[data-action]');if(!el)return;
if(el.dataset.lang){chooseLanguage(el.dataset.lang);return}
if(el.dataset.page){if(el.dataset.page==='lesson'&&el.dataset.lesson){const l=findLesson(el.dataset.lesson);if(l&&l.language===state.lang)seen(l.words[0].id)}navigate(el.dataset.page,el.dataset.lesson);return}
if(el.dataset.skill){state.practice=el.dataset.skill;state.word=0;state.typed='';state.feedback='';state.revealed=false;state.page='practice';if(state.practice==='listening')seen(allWords(state.lang)[0].id);render();return}
if(el.dataset.tab){state.practice=el.dataset.tab;state.word=0;state.revealed=false;state.feedback='';state.typed='';if(state.practice==='listening')seen(allWords(state.lang)[0].id);render();return}
if(el.dataset.step!==undefined){state.step=Number(el.dataset.step);state.word=0;state.answer=null;state.revealed=false;state.feedback='';render();return}
if(el.dataset.choice!==undefined){if(state.answer!==null)return;const l=lessonCurrent();const w=l.words[state.word];const choice=quizOptions(w)[Number(el.dataset.choice)];state.answer=Number(el.dataset.choice);recall(w.id,choice===w.meaning);render();return}
const action=el.dataset.action;switch(action){case'speak':doSpeak(el.dataset.text||'');break;case'record':doRecord();break;case'reveal':state.revealed=!state.revealed;if(state.revealed){if(state.page==='practice'&&state.practice==='listening')seen(allWords(state.lang)[state.word%allWords(state.lang).length].id);if(state.page==='lesson'&&state.step===0)seen(lessonCurrent().words[state.word].id)}render();break;case'next-step':nextStep();break;case'prev-step':previousStep();break;case'next-free':nextFree(1);break;case'path-next':state.pathPage++;render();break;case'path-previous':state.pathPage=Math.max(0,state.pathPage-1);render();break;case'library-more':state.libraryPage++;render();break;case'character-more':state.charPage++;render();break;case'grammar-more':state.grammarPage++;render();break;case'prev-free':nextFree(-1);break;case'mark-speak':markSpeak();break;case'mark-reading':markReading();break;case'check-writing':writingCheck();break;case'encounter':seen(el.dataset.word);render();toast('Word recorded as encountered.');break;case'bookmark':mutateWord(el.dataset.word,w=>w.marked=!w.marked);render();break;case'review-answer':doReview(el.dataset.word,el.dataset.correct==='true');break;case'open-conversation':{const href=data.settings.conversationUrl||'../#conversation';if(typeof href==='string'&&((href.startsWith('/')&&!href.startsWith('//'))||href.startsWith('#')||href==='../#conversation')){window.location.assign(href)}else toast('Set a safe internal route in Settings.');break}case'export':exportData();break;case'reset':if(confirm('Permanently erase BOTH Japanese and Chinese progress stored in this browser?')){data.progress=structuredClone(initial.progress);save();navigate('home');toast('Local progress reset.')}break;default:break;}});
root.addEventListener('input',e=>{const el=e.target;if(el.id==='character-search'){state.charQuery=el.value;state.charPage=0;render();const field=document.getElementById('character-search');if(field){field.focus();field.setSelectionRange(el.value.length,el.value.length)}return}if(el.id==='vocab-search'){state.search=el.value;state.libraryPage=0;const pos=el.selectionStart;render();const newEl=document.getElementById('vocab-search');newEl.focus();newEl.setSelectionRange(pos,pos)}if(el.id==='write-answer')state.typed=el.value});
root.addEventListener('change',async e=>{const el=e.target;if(el.id==='character-filter'){state.charFilter=el.value;state.charPage=0;render()}if(el.id==='grammar-filter'){state.grammarLevel=el.value;state.grammarPage=0;render()}if(el.id==='unit-filter'){state.unit=el.value;state.libraryPage=0;render()}if(el.id==='path-track'){selection().track=el.value;selection().level=el.value==='jlpt'?'N5':el.value==='old'||el.value==='new'?'1':'foundation';state.pathPage=0;data.settings.pathSelection=state.selection;save();render()}if(el.id==='path-level'){selection().level=el.value;state.pathPage=0;data.settings.pathSelection=state.selection;save();render()}if(el.id==='conversation-url'){const url=el.value.trim();if(!url||(url.startsWith('/')&&!url.startsWith('//'))||url.startsWith('#')){data.settings.conversationUrl=url;save();toast('Conversation route saved.')}else toast('Use an internal path beginning with / or #.')}if(el.id==='setting-audio'){data.settings.audio=el.checked;save();render()}if(el.id==='setting-roman'){data.settings.roman=el.checked;save();render()}if(el.id==='import-file'){const file=el.files?.[0];if(!file)return;if(file.size>2_000_000){toast('Import must be smaller than 2 MB.');return}try{const incoming=JSON.parse(await file.text());if(!validateImport(incoming)){toast('Not a valid Yukoto Hybrid v1 progress file.');return}if(!confirm('Replace your current Japanese and Chinese local progress with this backup?'))return;data.progress=incoming.progress;data.settings={...initial.settings,...incoming.settings};migrateImportedWordIds(data.progress.ja,jlptDataset.words,allWords('ja'));save();navigate('home');toast('Progress imported.') }catch{toast('Could not read this JSON backup.')}}});
window.addEventListener('beforeunload',()=>{if(window.speechSynthesis)window.speechSynthesis.cancel()});
render();
